@startuml

class Hospital {}

class Office {}

class User {}

class Doctor extends User {}

class Patient extends User {}

class Schedule {
  + Date : date
  + StartTime : time
  + EndTime : time
}

class Appointment {
  + DateTime : datetime
  + Duration : int
}

enum AppointmentType {
  BloodTest
  Consultation
  Surgery
}

Hospital "1" *-- "1..*" Office
Doctor "1" -- "*" Schedule : creates
Office "1" -- "*" Schedule : has
Doctor "1" -- "*" Appointment : has
Patient "1" -- "*" Appointment : books
Schedule "1" -- "0..*" Appointment : for
Appointment "1" -- "1" AppointmentType : is of type

@enduml

